'use strict';
const $=s=>document.querySelector(s), canvas=$('#battle'),ctx=canvas.getContext('2d');
const W=1440,H=650,lanes=[285,418,551];
const creatures=[{name:'Frostfang',role:'DIREWOLF · SWIFT STRIKER',cost:40,hp:150,atk:22,speed:52,range:42,rate:.75,size:80,cell:0,color:'#b4c8c8',lore:'A direwolf from the frozen northern wilds. Fast and inexpensive; overwhelms isolated enemies.'},{name:'Sunclaw',role:'GRIFFIN · SKY HUNTER',cost:70,hp:230,atk:36,speed:39,range:80,rate:1.1,size:103,cell:1,color:'#cda85d',lore:'Born above the sun temples. Its sweeping strikes reach enemies before they can close the distance.'},{name:'Emberwing',role:'DRAGON · FIRE BREATHER',cost:110,hp:340,atk:62,speed:29,range:145,rate:1.45,size:140,cell:2,color:'#c35f3e',lore:'The last of an ancient fire bloodline. Breathes flame across clustered enemies in the same lane.'},{name:'Runestone',role:'GOLEM · ANCIENT GUARDIAN',cost:90,hp:650,atk:42,speed:19,range:53,rate:1.5,size:105,cell:3,color:'#83a89a',lore:'An ancient guardian carved from living stone. Slow moving, but its immense health shields the army.'},{name:'Rimewraith',role:'WYVERN · FROST REAPER',cost:100,hp:270,atk:43,speed:35,range:125,rate:1.2,size:122,cell:4,color:'#89c6d8',lore:'An icy wyvern awakened beneath the mountains. Ranged attacks slow its target for two seconds.'}];
const bg=new Image(),atlas=new Image();bg.src='assets/battlefield.png';atlas.src='assets/creatures.png';let atlasLoaded=false;atlas.onload=()=>{atlasLoaded=true;drawCards()};
let state,selected=2,lane=1,speed=1,sound=false,audioContext,last=0,id=0;
function reset(){state={running:false,started:false,finished:false,time:0,mana:180,ally:2400,enemy:2400,units:[],particles:[],effects:[],spawnIn:3.5,wave:1,kills:0,evolution:0,fireCD:0,shake:0};speed=1;$('#speed').textContent='1×';$('#pause').textContent='Ⅱ';$('#start-screen').classList.remove('hidden');$('#result').classList.add('hidden');updateUI()}
function start(){reset();state.running=true;state.started=true;$('#start-screen').classList.add('hidden');tone(180,.15);setTimeout(()=>tone(270,.2),120);for(let l=0;l<3;l++){spawn(0,l,1,220+l*28);spawn(l===1?3:0,l,-1,1070+l*25)}updateUI()}
function tone(freq,duration=.1,type='sine',vol=.04){if(!sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioContext.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.5,audioContext.currentTime+duration);g.gain.setValueAtTime(vol,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);o.connect(g);g.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+duration)}catch{}}
function spawn(type,l,team,x){const c=creatures[type],mult=team===1?1+state.evolution*.25: .78+state.wave*.085;const u={id:id++,type,lane:l,team,x:x??(team===1?150:1290),hp:c.hp*mult,maxhp:c.hp*mult,atk:c.atk*mult,cd:.4,phase:Math.random()*10,hit:0,slow:0};state.units.push(u);burst(u.x,lanes[l]-20,team===1?'#d5c48b':'#a9bfd1',12);return u}
function deploy(){if(!state.started||state.finished)return;if(!state.running){hint('Resume the battle to summon.');return}let c=creatures[selected];if(state.mana<c.cost){hint('More essence is needed for '+c.name+'.');tone(80);return}state.mana-=c.cost;spawn(selected,lane,1);hint(c.name+' summoned to lane '+['I','II','III'][lane]+'.');tone(200+selected*60,.16);updateUI()}
function select(i){selected=i;document.querySelectorAll('.creature').forEach((el,j)=>el.classList.toggle('selected',j===i));hint(creatures[i].name+' selected · click a lane to summon.')}
function chooseLane(l){lane=l;document.querySelectorAll('[data-lane]').forEach((el,i)=>el.classList.toggle('active',i===l))}
function hint(s){$('#tip').innerHTML=s+'<small>Keys 1–5 select · ↑ ↓ choose lane · Enter deploys · Space pauses</small>'}
function burst(x,y,color,n=8){for(let i=0;i<n;i++)state.particles.push({x,y,vx:(Math.random()-.5)*100,vy:-Math.random()*100,life:.4+Math.random()*.6,max:1,color,size:1+Math.random()*3})}
function fire(){if(!state.running||state.fireCD>0)return;state.fireCD=30;state.effects.push({kind:'fire',lane,life:1.4});state.shake=10;state.units.filter(u=>u.team===-1&&u.lane===lane).forEach(u=>{u.hp-=200;u.hit=.3;burst(u.x,lanes[lane]-30,'#ffb75a',25)});tone(75,.7,'sawtooth',.08);hint('Dragonfire scorched lane '+['I','II','III'][lane]+'.')}
function evolve(){const cost=120+state.evolution*80;if(!state.running||state.evolution>=3)return;if(state.mana<cost){hint('You need '+cost+' essence to evolve your army.');return}state.mana-=cost;state.evolution++;state.units.filter(u=>u.team===1).forEach(u=>{const hp=creatures[u.type].hp*.25;u.hp+=hp;u.maxhp+=hp;u.atk+=creatures[u.type].atk*.25;burst(u.x,lanes[u.lane]-40,'#eddb8b',20)});tone(420,.4,'sine');hint('Evolution '+state.evolution+' · your army grows stronger.');updateUI()}
function togglePause(){if(!state.started||state.finished)return;state.running=!state.running;$('#pause').textContent=state.running?'Ⅱ':'▶';updateUI()}
function update(dt){if(!state.running)return;dt*=speed;state.time+=dt;state.mana=Math.min(400,state.mana+12*dt);state.fireCD=Math.max(0,state.fireCD-dt);state.wave=Math.min(5,1+Math.floor(state.time/26));state.spawnIn-=dt;if(state.spawnIn<=0){const r=Math.random(),type=state.wave<2?(r>.75?3:0):r>.8?2:r>.55?4:r>.32?1:0;spawn(type,Math.floor(Math.random()*3),-1);state.spawnIn=Math.max(2.5,6.4-state.wave*.65);if(state.wave===5&&Math.random()>.4)spawn(3,Math.floor(Math.random()*3),-1)}
for(const u of state.units){if(u.hp<=0)continue;const c=creatures[u.type];u.cd-=dt;u.hit=Math.max(0,u.hit-dt);u.slow=Math.max(0,u.slow-dt);u.phase+=dt*(u.slow>0?3:7);const enemies=state.units.filter(e=>e.hp>0&&e.team!==u.team&&e.lane===u.lane&&(e.x-u.x)*u.team>-25).sort((a,b)=>Math.abs(a.x-u.x)-Math.abs(b.x-u.x));const target=enemies[0],dist=target?Math.abs(target.x-u.x):Infinity;const baseDist=u.team===1?1300-u.x:u.x-140;
if(dist<c.range||baseDist<c.range){if(u.cd<=0){u.cd=c.rate;if(dist<c.range){target.hp-=u.atk;target.hit=.18;if(u.type===4)target.slow=2;if(u.type===2){for(const e of enemies.slice(1))if(Math.abs(e.x-target.x)<95){e.hp-=u.atk*.5;e.hit=.18}state.effects.push({kind:'breath',x:u.x+u.team*45,y:lanes[u.lane]-48,team:u.team,life:.4,color:u.team===1?'#e89645':'#92b7d1'})}burst(target.x,lanes[u.lane]-35,c.color,6)}else{if(u.team===1)state.enemy=Math.max(0,state.enemy-u.atk);else state.ally=Math.max(0,state.ally-u.atk);state.shake=3;burst(u.team===1?1300:140,lanes[u.lane]-50,'#dfac68',10)}tone(90+u.type*25,.05,'triangle',.01)}}else u.x+=u.team*c.speed*(u.slow>0?.5:1)*dt}
state.units=state.units.filter(u=>{if(u.hp<=0){burst(u.x,lanes[u.lane]-30,creatures[u.type].color,15);if(u.team===-1){state.kills++;state.mana=Math.min(400,state.mana+13)}return false}return true});state.particles=state.particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=100*dt;return p.life>0});state.effects=state.effects.filter(e=>(e.life-=dt)>0);state.shake=Math.max(0,state.shake-dt*25);if(state.ally<=0||state.enemy<=0)finish(state.enemy<=0);updateUI()}
function finish(win){state.running=false;state.finished=true;$('#result').classList.remove('hidden');$('#result-kicker').textContent=win?'BLACKTHORN HAS FALLEN':'THE EMBERS WILL RISE AGAIN';$('#result-title').textContent=win?'The crown is yours.':'Your stronghold has fallen.';$('#result-copy').textContent=(win?'A new legend begins. ':'Regroup and choose your lanes carefully. ')+state.kills+' enemies defeated · '+Math.floor(state.time)+' seconds · evolution '+state.evolution;tone(win?500:100,.6)}
function updateUI(){$('#mana').textContent=Math.floor(state.mana);$('#ally-hp').textContent=Math.ceil(state.ally).toLocaleString()+' / 2,400';$('#enemy-hp').textContent=Math.ceil(state.enemy).toLocaleString()+' / 2,400';$('#ally-bar').style.width=state.ally/24+'%';$('#enemy-bar').style.width=state.enemy/24+'%';$('#wave').innerHTML='WAVE 0'+state.wave+' <em>/ 05</em>';$('#timer').textContent=String(Math.floor(state.time/60)).padStart(2,'0')+':'+String(Math.floor(state.time%60)).padStart(2,'0');$('#battle-state').textContent=state.finished?'BATTLE ENDED':state.running?'SIEGE IN PROGRESS':state.started?'BATTLE PAUSED':'AWAITING YOUR COMMAND';$('#fire').disabled=!state.running||state.fireCD>0;$('#fire-status').textContent=state.fireCD>0?'Recharging · '+Math.ceil(state.fireCD)+' sec':'Scorch a lane · ready';$('#evolve').disabled=!state.running||state.evolution>=3;$('#evolve-tier').textContent=['I','II','III','IV'][state.evolution];$('#evolve-cost').textContent=state.evolution>=3?'Maximum evolution reached':(120+state.evolution*80)+' essence · +25% strength';document.querySelectorAll('.creature').forEach((el,i)=>el.classList.toggle('unaffordable',state.mana<creatures[i].cost))}
function fallbackCreature(g,type,x,y,size,team,phase){g.save();g.translate(x,y);g.scale(team*size/100,size/100);const c=creatures[type];g.fillStyle=c.color;g.strokeStyle='#182321';g.lineWidth=2;if(type===3){for(let j=0;j<5;j++){g.fillStyle=j%2?'#819186':'#5f7368';g.fillRect(-25+j%2*14,-65+j*10,40,24)}g.fillStyle='#9bdbb9';g.fillRect(13,-60,8,5)}else{g.beginPath();g.ellipse(0,-24,30,16,0,0,7);g.fill();g.beginPath();g.moveTo(20,-30);g.lineTo(38,-49);g.lineTo(57,-30);g.lineTo(31,-25);g.closePath();g.fill();for(let j=0;j<4;j++){let xx=-20+j*13;g.fillRect(xx,-18,6,20+Math.sin(phase+j)*5)}g.beginPath();g.moveTo(-20,-27);g.quadraticCurveTo(-65,-55,-50,-4);g.lineTo(-13,-20);g.fill();if(type===1||type===2||type===4){const flap=Math.sin(phase)*13;g.globalAlpha=.9;g.beginPath();g.moveTo(-10,-30);g.lineTo(-45,-95+flap);g.lineTo(12,-65+flap);g.lineTo(32,-28);g.closePath();g.fill();g.stroke()}g.fillStyle='#ffdc97';g.fillRect(38,-38,5,4)}g.restore()}
function sprite(g,type,x,y,size,team,phase,hit=false){if(!atlasLoaded){fallbackCreature(g,type,x,y,size,team,phase);return}const cell=creatures[type].cell,cw=atlas.width/3,ch=atlas.height/2;g.save();g.translate(x,y+Math.sin(phase)*2);g.scale(team,1);if(hit)g.filter='brightness(1.8)';g.drawImage(atlas,(cell%3)*cw,Math.floor(cell/3)*ch,cw,ch,-size*.65,-size*.89,size*1.3,size);g.restore()}
function draw(){ctx.clearRect(0,0,W,H);if(bg.complete&&bg.naturalWidth){ctx.drawImage(bg,0,0,W,H)}else{ctx.fillStyle='#26342d';ctx.fillRect(0,0,W,H)}const shade=ctx.createLinearGradient(0,0,0,H);shade.addColorStop(0,'#06100e30');shade.addColorStop(.4,'#121d1722');shade.addColorStop(1,'#07100be0');ctx.fillStyle=shade;ctx.fillRect(0,0,W,H);ctx.save();if(state.shake)ctx.translate((Math.random()-.5)*state.shake,(Math.random()-.5)*state.shake);
for(let i=0;i<3;i++){ctx.fillStyle=i===lane?'#c9af6620':'#5e79680a';ctx.fillRect(170,lanes[i]-74,1100,112);ctx.strokeStyle=i===lane?'#cbb57855':'#bdc6a319';ctx.setLineDash([6,13]);ctx.beginPath();ctx.moveTo(175,lanes[i]+38);ctx.lineTo(1265,lanes[i]+38);ctx.stroke();ctx.setLineDash([])}
for(const u of [...state.units].sort((a,b)=>a.lane-b.lane)){const c=creatures[u.type],y=lanes[u.lane];ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(u.x,y+8,c.size*.28,7,0,0,7);ctx.fill();sprite(ctx,u.type,u.x,y,c.size,u.team,u.phase,u.hit>0);const bw=Math.min(64,c.size*.6);ctx.fillStyle='#0a110dbb';ctx.fillRect(u.x-bw/2,y-c.size*.88-6,bw,4);ctx.fillStyle=u.team===1?'#9cc6ad':'#d59a7a';ctx.fillRect(u.x-bw/2,y-c.size*.88-6,bw*Math.max(0,u.hp/u.maxhp),4);if(u.team===1&&state.evolution){ctx.fillStyle='#d7b96c';ctx.font='11px serif';ctx.fillText('✧'.repeat(state.evolution),u.x-10,y+28)}}
for(const e of state.effects){if(e.kind==='fire'){const y=lanes[e.lane];const grad=ctx.createLinearGradient(200,y,1250,y);grad.addColorStop(0,'#ffc76b00');grad.addColorStop(.5,'#ffb137aa');grad.addColorStop(1,'#ff542a33');ctx.globalAlpha=Math.min(1,e.life);ctx.fillStyle=grad;ctx.fillRect(180,y-90,1080,105);for(let j=0;j<30;j++){ctx.fillStyle=j%2?'#ffce75':'#f97b38';ctx.beginPath();ctx.arc(220+j*34,y-25-Math.random()*65,6+Math.random()*12,0,7);ctx.fill()}ctx.globalAlpha=1}else{ctx.save();ctx.translate(e.x,e.y);ctx.scale(e.team,1);ctx.globalAlpha=e.life*2;const grad=ctx.createLinearGradient(0,0,125,0);grad.addColorStop(0,e.color);grad.addColorStop(1,'#ffb94a00');ctx.fillStyle=grad;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(140,-35);ctx.lineTo(140,35);ctx.closePath();ctx.fill();ctx.restore()}}
for(const p of state.particles){ctx.globalAlpha=Math.min(1,p.life*2);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)}ctx.globalAlpha=1;ctx.restore();const t=performance.now()/1000;for(let i=0;i<28;i++){ctx.globalAlpha=.2+.3*Math.sin(t+i);ctx.fillStyle=i%3?'#dfa263':'#e4c78a';ctx.fillRect((i*173+t*(8+i%5))%W,H-((i*79+t*(13+i%7))%H),1.5,1.5)}ctx.globalAlpha=1;if(state.started&&!state.running&&!state.finished){ctx.fillStyle='#06100d80';ctx.fillRect(0,0,W,H);ctx.fillStyle='#e0d4b7';ctx.textAlign='center';ctx.font='30px Georgia';ctx.fillText('BATTLE PAUSED',W/2,H/2);ctx.textAlign='left'}}
function drawCards(){document.querySelectorAll('.portrait canvas').forEach((c,i)=>{const g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);sprite(g,i,c.width/2,105,125,1,0)})}
$('#roster').innerHTML=creatures.map((c,i)=>`<button class="creature ${i===selected?'selected':''}" data-creature="${i}" aria-label="Select ${c.name}, ${c.cost} essence"><div class="portrait"><canvas width="260" height="120"></canvas></div><span class="key">${i+1}</span><span class="cost">${c.cost}</span><span class="name">${c.name}</span><span class="role">${c.role}</span><span class="rarity"></span></button>`).join('');document.querySelectorAll('[data-creature]').forEach(el=>el.onclick=()=>select(+el.dataset.creature));document.querySelectorAll('[data-lane]').forEach(el=>el.onclick=()=>chooseLane(+el.dataset.lane));canvas.onclick=e=>{if(!state.running)return;const r=canvas.getBoundingClientRect(),y=(e.clientY-r.top)/r.height*H;chooseLane(lanes.reduce((best,v,i)=>Math.abs(v-y)<Math.abs(lanes[best]-y)?i:best,0));deploy()};$('#start').onclick=start;$('#restart').onclick=start;$('#pause').onclick=togglePause;$('#speed').onclick=()=>{speed=speed===1?2:1;$('#speed').textContent=speed+'×'};$('#fire').onclick=fire;$('#evolve').onclick=evolve;$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'♫':'♪';$('#sound').style.color=sound?'#d9ba7a':'#adb2a9';tone(300)};
function modal(codex){$('#modal-title').textContent=codex?'The ancient bestiary':'How to conquer';$('#modal-content').innerHTML=codex?creatures.map(c=>`<div class="codex-entry"><b>${c.name}</b><p>${c.lore}<br>${c.cost} essence · ${c.hp} health · ${c.atk} damage</p></div>`).join(''):'<p><strong>1. Choose your creature.</strong> Select a card below the battlefield or press 1–5.</p><p><strong>2. Command a lane.</strong> Click any of the three lanes to summon. Your creatures march and attack automatically. Essence regenerates at 12 per second; defeated enemies award 13 more.</p><p><strong>3. Turn the tide.</strong> Evolve your entire army for extra health and damage. Press F to unleash dragonfire on your selected lane.</p><p><strong>4. Claim the crown.</strong> Destroy the enemy citadel before your stronghold falls. Space pauses; the 1× button changes battle speed.</p>';$('#modal').showModal()}$('#help').onclick=()=>modal(false);$('#codex').onclick=()=>modal(true);$('#close-modal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};document.addEventListener('keydown',e=>{if($('#modal').open)return;if(e.key>='1'&&e.key<='5')select(+e.key-1);if(['ArrowUp','ArrowDown','Enter',' '].includes(e.key))e.preventDefault();if(e.key==='ArrowUp')chooseLane((lane+2)%3);if(e.key==='ArrowDown')chooseLane((lane+1)%3);if(e.key==='Enter')state.started?deploy():start();if(e.key===' ')togglePause();if(e.key.toLowerCase()==='f')fire()});
reset();drawCards();function frame(t){const dt=Math.min((t-last)/1000,.05);last=t;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
window.emberfall={getState:()=>structuredClone(state),select,chooseLane,deploy,start,fire,evolve,togglePause};
